// Run with Node 22+ and Chrome; set CHROME_BIN when Chrome is not at the platform default.
const assert = require('node:assert/strict');
const http = require('node:http');
const fs = require('node:fs/promises');
const path = require('node:path');
const {spawn} = require('node:child_process');
const {once} = require('node:events');
const {setTimeout: delay} = require('node:timers/promises');
const root=path.resolve(__dirname,'../static');
const profile=path.join(require('node:os').tmpdir(),'streamanalyzer-automatic-ui-'+process.pid);
const chromePath=process.env.CHROME_BIN||(process.platform==='darwin'?'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome':process.platform==='win32'?'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe':'google-chrome');
async function until(f){for(let n=0;n<100;n++){const result=await f();if(result)return result;await delay(100);}throw new Error('Timeout');}
(async()=>{
 const server=http.createServer(async(req,res)=>{
  if(req.url.startsWith('/api/')){res.setHeader('Content-Type','application/json');res.end(req.url.endsWith('/config')?'{}':'[]');return;}
  const name=req.url==='/diagnostics'?'diagnostics.html':req.url.replace(/^\/static\//,'');
  try{const body=await fs.readFile(path.join(root,name));res.setHeader('Content-Type',name.endsWith('.js')?'text/javascript':name.endsWith('.css')?'text/css':'text/html');res.end(body);}catch{res.writeHead(404).end();}
 });
 server.listen(0,'127.0.0.1');await once(server,'listening');
 const chrome=spawn(chromePath,['--headless=new','--disable-gpu','--no-first-run',`--user-data-dir=${profile}`,'--remote-debugging-port=0','about:blank'],{stdio:'ignore'});
 let ws;
 try{
  const debug=await until(()=>fs.readFile(path.join(profile,'DevToolsActivePort'),'utf8').catch(()=>''));
  const tabs=await(await fetch(`http://127.0.0.1:${debug.split('\n')[0]}/json/list`)).json();
  ws=new WebSocket(tabs.find(tab=>tab.type==='page').webSocketDebuggerUrl);await once(ws,'open');
  const pending=new Map();let n=0;const errors=[];
  ws.addEventListener('message',({data})=>{const msg=JSON.parse(data);if(msg.id){const item=pending.get(msg.id);pending.delete(msg.id);msg.error?item.reject(msg.error):item.resolve(msg.result);}else if(msg.method==='Runtime.exceptionThrown')errors.push(msg.params);});
  const cdp=(method,params={})=>new Promise((resolve,reject)=>{pending.set(++n,{resolve,reject});ws.send(JSON.stringify({id:n,method,params}));});
  const evaluate=async expression=>{const result=await cdp('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,replMode:true});if(result.exceptionDetails)throw new Error(JSON.stringify(result.exceptionDetails));return result.result.value;};
  await cdp('Runtime.enable');await cdp('Page.navigate',{url:`http://127.0.0.1:${server.address().port}/diagnostics`});
  await until(()=>evaluate(`typeof renderRequestTiming === 'function'`).catch(()=>false));
  await evaluate(`window.autoPosts=[];window.autoReads=0;window.autoDetail={id:'auto-ui',mode:'sample',status:'done',protocol:'http-flv',created_at:'2026-11-19T00:00:00Z',origin:'https://example.test/live.flv',report:null,automatic_running:false};window.fetch=async(url,options={})=>{let value;if(options.method==='POST'){autoPosts.push({url,body:JSON.parse(options.body||'{}')});if(url.endsWith('/runs'))value={id:'auto-ui',protocol:'http-flv'};else if(url.endsWith('/automatic/stop')){autoDetail.automatic_running=false;autoDetail.report.automatic_investigation.state='canceled';autoDetail.report.automatic_investigation.model_state='canceled';value={status:'stopping'};}else if(url.endsWith('/automatic/retry')){autoDetail.automatic_running=true;autoDetail.report.automatic_investigation.state='investigating';autoDetail.report.automatic_investigation.model_state='pending';value=autoDetail.report.automatic_investigation;}else value={};}else if(url.endsWith('/runs/auto-ui')){autoReads++;value=autoDetail;}else if(url.endsWith('/runs'))value=[autoDetail];else value={model_configured:false};return new Response(JSON.stringify(value),{status:200,headers:{'Content-Type':'application/json'}});};`);
  assert.equal(await evaluate(`document.getElementById('auto-investigate').checked`),true);assert.equal(await evaluate(`document.getElementById('auto-investigate').disabled`),true);
  await evaluate(`document.getElementById('analyze-playback').checked=true;document.getElementById('analyze-playback').dispatchEvent(new Event('change'))`);assert.equal(await evaluate(`document.getElementById('auto-investigate').disabled`),false);
  await evaluate(`document.getElementById('auto-investigate').checked=false;document.getElementById('analyze-playback').checked=false;document.getElementById('analyze-playback').dispatchEvent(new Event('change'));document.getElementById('analyze-playback').checked=true;document.getElementById('analyze-playback').dispatchEvent(new Event('change'))`);assert.equal(await evaluate(`document.getElementById('auto-investigate').checked`),false,'preview toggle lost explicit automatic opt-out');
  await evaluate(`document.getElementById('auto-investigate').checked=true;document.getElementById('url').value='https://example.test/live.flv';document.getElementById('sample').requestSubmit()`);await until(()=>evaluate(`autoPosts.some(v=>v.url.endsWith('/runs'))`));assert.equal(await evaluate(`autoPosts.find(v=>v.url.endsWith('/runs')).body.auto_investigate`),true);
  const interval={start_ms:1000,end_ms:5000,duration_ms:4000};const report={manifest:{protocol:'http-flv',stream:{bytes:128},observation:{started_at:'2026-11-19T00:00:00Z',elapsed_ms:8000,requested_seconds:8,end_reason:'duration_limit',stages:[]}},metrics:{video_frames:0,audio_frames:0},findings:[],player:{state:'complete',source:'same_capture',revision:2,active_ms:8000,stall_count:1,total_stall_ms:4000,max_stall_ms:4000,stall_ratio:.5,buffer_samples:[],stalls:[interval],events:[]},automatic_investigation:{version:1,policy:'critical_intervals_v1',state:'investigating',player_revision:2,candidate_count:4,model_state:'pending',selected:[{interval_kind:'buffering',interval_index:1,interval,case_id:'S001'},{interval_kind:'presentation_gap',interval_index:2,interval:{start_ms:6000,end_ms:9000,duration_ms:3000},case_id:'S002'}]},stall_investigations:[{id:'S001',stall_index:1,player_revision:2,status:'complete',stall:interval,correlation:{source:'same_capture',window_start_ms:0,window_end_ms:8000,findings:[]},media:{status:'ready',assets:[]},model_state:'not_requested'},{id:'S002',stall_index:2,interval_kind:'presentation_gap',player_revision:2,status:'partial',stall:{start_ms:6000,end_ms:9000,duration_ms:3000},correlation:{source:'same_capture',window_start_ms:3000,window_end_ms:8000,findings:[]},media:{status:'partial',assets:[]},model_state:'not_requested'}]};
  await evaluate(`autoDetail.report=${JSON.stringify(report)};autoDetail.automatic_running=true;await selectRun('auto-ui')`);
  let text=await evaluate(`document.getElementById('automatic-investigation-content').textContent`);for(const label of ['当前阶段 · 正在提取异常证据','候选同期异常区间4','自动选择2 个 / 最多 3 个','6000 ms–9000 ms','2000 ms','媒体产物部分可用','整体汇总状态尚未生成'])assert.ok(text.includes(label),label);
  assert.match(await evaluate(`document.getElementById('stall-investigation-results').textContent`),/未单独解读/);assert.equal(await evaluate(`document.querySelector('[data-stall-explain="S001"]').disabled`),true);
  await evaluate(`document.querySelector('[data-automatic-action="stop"]').click()`);await until(()=>evaluate(`autoPosts.some(v=>v.url.endsWith('/automatic/stop'))`));assert.deepEqual(await evaluate(`autoPosts.find(v=>v.url.endsWith('/automatic/stop')).body`),{});
  await evaluate(`autoDetail.mode='replay';autoDetail.automatic_running=false;autoDetail.report.automatic_investigation.state='investigating';await selectRun('auto-ui')`);assert.match(await evaluate(`document.getElementById('automatic-investigation-content').textContent`),/已导入记录，不自动续跑/);assert.equal(await evaluate(`document.querySelector('[data-automatic-action]').dataset.automaticAction`),'retry');const reads=await evaluate('autoReads');await delay(1050);assert.equal(await evaluate('autoReads'),reads,'imported unfinished metadata triggered automatic polling');
  await evaluate(`document.querySelector('[data-automatic-action="retry"]').click()`);await until(()=>evaluate(`autoPosts.some(v=>v.url.endsWith('/automatic/retry'))&&currentAutomaticRunning`));assert.equal(await evaluate(`document.querySelector('[data-automatic-action]').dataset.automaticAction`),'stop');const runningReads=await evaluate('autoReads');await delay(1050);assert.ok(await evaluate('autoReads')>runningReads,'explicit imported retry did not poll live runtime task');
  await evaluate(`autoDetail.automatic_running=false;autoDetail.report.automatic_investigation.state='unconfigured';autoDetail.report.automatic_investigation.model_state='unconfigured';await refreshDetail('auto-ui')`);text=await evaluate(`document.getElementById('automatic-investigation-content').textContent`);assert.ok(text.includes('模型尚未配置')&&text.includes('整体汇总状态未配置模型'));
  for(const width of [1440,375]){await cdp('Emulation.setDeviceMetricsOverride',{width,height:1000,deviceScaleFactor:1,mobile:false});assert.equal(await evaluate(`document.documentElement.scrollWidth>innerWidth`),false,'automatic table overflow at '+width);}
  await evaluate(`autoDetail.report.automatic_investigation={...autoDetail.report.automatic_investigation,state:'waiting_player',player_revision:0,candidate_count:0,selected:[]};await refreshDetail('auto-ui')`);text=await evaluate(`document.getElementById('automatic-investigation-content').textContent`);assert.ok(text.includes('尚未记录选择结果')&&!text.includes('未选出可补查的同期异常'));
  await evaluate(`autoDetail.report.automatic_investigation={...autoDetail.report.automatic_investigation,state:'complete',player_revision:2,model_state:'complete'};await refreshDetail('auto-ui')`);assert.match(await evaluate(`document.getElementById('automatic-investigation-content').textContent`),/未选出可补查的同期异常/);
  await evaluate(`delete autoDetail.report.automatic_investigation;await refreshDetail('auto-ui')`);assert.equal(await evaluate(`document.getElementById('automatic-investigation').hidden`),true);
  assert.equal(await evaluate(`new Set(Array.from(document.querySelectorAll('[id]')).map(v=>v.id)).size===document.querySelectorAll('[id]').length`),true);assert.equal(errors.length,0,JSON.stringify(errors));console.log(JSON.stringify({result:'PASS',cases:['default opt-in linked to preview and explicit opt-out retained','true UI API flag','workflow stages and clipped overlap versus original intervals','media-only case not_requested','stop/retry exact APIs','import pending is historical and never polls','explicit replay retry uses runtime marker','unconfigured summary distinct from media','zero candidates versus pending unknown','legacy absent and375/1440 layout']}));
 }finally{ws?.close();chrome.kill('SIGTERM');await once(chrome,'exit').catch(()=>{});server.close();await fs.rm(profile,{recursive:true,force:true,maxRetries:5,retryDelay:100});}
})().catch(err=>{console.error(err);process.exitCode=1;});
